import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.CZo9GF0W.js";const p=JSON.parse('{"title":"Redis, Sentinel and Cluster","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/redis.md","filePath":"recipes/redis.md","lastUpdated":1789060268000}'),s={name:"recipes/redis.md"};function r(n,e,i,l,c,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="redis-sentinel-and-cluster" tabindex="-1">Redis, Sentinel and Cluster <a class="header-anchor" href="#redis-sentinel-and-cluster" aria-label="Permalink to &quot;Redis, Sentinel and Cluster&quot;">​</a></h1><h2 id="standalone" tabindex="-1">Standalone <a class="header-anchor" href="#standalone" aria-label="Permalink to &quot;Standalone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Mode</td><td><code>Standalone</code></td></tr><tr><td>Host</td><td><code>localhost</code>, port <code>6379</code></td></tr><tr><td>Database</td><td><code>0</code> — a numeric index, not a name</td></tr><tr><td>Username</td><td>leave empty, or <code>default</code> on Redis 6+ with ACLs</td></tr><tr><td>Password</td><td>the ACL password, or the <code>requirepass</code> value</td></tr><tr><td>TLS</td><td>off locally; <code>verify-full</code> for anything managed</td></tr></tbody></table><h2 id="sentinel" tabindex="-1">Sentinel <a class="header-anchor" href="#sentinel" aria-label="Permalink to &quot;Sentinel&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Mode</td><td><code>Sentinel</code></td></tr><tr><td>Nodes</td><td>the <strong>sentinel</strong> addresses as <code>host:port</code>, one per entry</td></tr><tr><td>Master name</td><td><code>mymaster</code>, or whatever your sentinels call it</td></tr><tr><td>Database</td><td>the numeric index</td></tr></tbody></table><p>The client asks a sentinel where the master is and connects to the answer, so the addresses the sentinels return must be reachable from the machine Pitta is on.</p><h2 id="cluster" tabindex="-1">Cluster <a class="header-anchor" href="#cluster" aria-label="Permalink to &quot;Cluster&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Mode</td><td><code>Cluster</code></td></tr><tr><td>Nodes</td><td>seed nodes as <code>host:port</code> — any two or three, the rest are discovered</td></tr><tr><td>Database</td><td>not shown: cluster mode has only database 0</td></tr></tbody></table><p>Pitta handles the cluster shape rather than hiding it: a command that would span slots is split per node where that is meaningful and <strong>refused with the fix</strong> where it is not. <code>DBSIZE</code> and the keyspace scan run across the nodes.</p><h2 id="managed-redis" tabindex="-1">Managed Redis <a class="header-anchor" href="#managed-redis" aria-label="Permalink to &quot;Managed Redis&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Notes</th></tr></thead><tbody><tr><td>ElastiCache</td><td>In-VPC. Connect from a VM over Remote-SSH. Cluster mode enabled → <code>Cluster</code>. In-transit encryption on → TLS <code>verify-full</code>.</td></tr><tr><td>Azure Cache for Redis</td><td>Port <strong>6380</strong> for TLS; 6379 is non-TLS and usually disabled. Password is the access key.</td></tr><tr><td>Redis Cloud</td><td>Host and port from the console, TLS on, <code>default</code> user unless you made an ACL.</td></tr><tr><td>Upstash</td><td>TLS required. The REST API is a different product — use the Redis protocol endpoint.</td></tr></tbody></table><h2 id="tunnels" tabindex="-1">Tunnels <a class="header-anchor" href="#tunnels" aria-label="Permalink to &quot;Tunnels&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Sentinel and Cluster refuse an SSH tunnel</p><p>Both discover node addresses after connecting, and those addresses only resolve on the bastion&#39;s side. One forwarded port cannot serve them. <strong>Standalone</strong> tunnels normally.</p><p>Use a VPN, or attach VS Code to a machine inside the network. See <a href="./ssh">the SSH recipe</a>.</p></div><h2 id="browsing-a-large-keyspace" tabindex="-1">Browsing a large keyspace <a class="header-anchor" href="#browsing-a-large-keyspace" aria-label="Permalink to &quot;Browsing a large keyspace&quot;">​</a></h2><p>The tree is built with <code>SCAN</code> in bounded pages, never <code>KEYS</code>, and prefix folders come from a sample rather than from a full enumeration. Pointing Pitta at a million-key instance is not supposed to be something the server notices — the project&#39;s own acceptance test for this checks <code>SLOWLOG</code> and <code>INFO commandstats</code> afterwards.</p><p><code>keySeparator</code> (default <code>:</code>) decides how keys fold into folders. <code>scanCount</code> tunes how much each <code>SCAN</code> asks for.</p><p>Keys are deliberately <strong>not</strong> offered in completion. A keyspace cannot be listed cheaply, which is the same reason the tree pages.</p><h2 id="values-and-ttl" tabindex="-1">Values and TTL <a class="header-anchor" href="#values-and-ttl" aria-label="Permalink to &quot;Values and TTL&quot;">​</a></h2><p>Each type opens in the view it deserves: string, hash, list, set, sorted set, stream with its consumer groups, and RedisJSON documents where the module is loaded.</p><p><strong>TTL is a first-class, editable field.</strong> <strong>Pitta: Set Expiry…</strong> sets or clears it, and clearing is <code>PERSIST</code> rather than an expiry of zero.</p><h2 id="guards" tabindex="-1">Guards <a class="header-anchor" href="#guards" aria-label="Permalink to &quot;Guards&quot;">​</a></h2><p>The command list and its flags come from the connected server&#39;s own <code>COMMAND INFO</code> / <code>COMMAND DOCS</code>, so a module command this build has never heard of is still classified, still completes and still hovers.</p><ul><li><strong><code>KEYS</code> is refused</strong>, not confirmed: it walks the entire keyspace and blocks the server while it does. <code>pitta.redis.allowKeysCommand</code> exists if you insist.</li><li><strong><code>MONITOR</code> is refused</strong> by default and always on production: it makes the server report every command it runs to this client and measurably slows it for everyone. When allowed, it time-boxes itself (<code>pitta.redis.monitorSeconds</code>, default 10).</li><li><code>FLUSHALL</code>, <code>FLUSHDB</code>, <code>SWAPDB</code>, <code>CONFIG SET</code>, <code>SHUTDOWN</code>, <code>MIGRATE</code>, <code>REPLICAOF</code>, <code>CLUSTER RESET</code>, <code>ACL SETUSER</code> and <code>EVAL</code> need the typed confirmation on a <code>prod</code> connection.</li><li>An <strong>unknown</strong> command on production is treated as destructive. Unknown fails closed.</li><li>Edits are previewed as a command list and applied in <code>MULTI</code>/<code>EXEC</code> where the slots allow. Where they do not, the dialog says there is no rollback, in those words.</li><li><code>readOnly</code> is enforced in the client and the badge says <strong>client-side only</strong>. The server-side equivalent is an ACL: <code>ACL SETUSER pitta on &gt;pw ~* +@read</code>.</li></ul><h2 id="pub-sub" tabindex="-1">Pub/Sub <a class="header-anchor" href="#pub-sub" aria-label="Permalink to &quot;Pub/Sub&quot;">​</a></h2><p><strong>Pitta: Subscribe to Channels</strong> streams messages into a panel, including keyspace notifications. The keyspace patterns are offered only when <code>notify-keyspace-events</code> is actually configured to emit them, rather than listed and silently empty.</p>',25)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
